"""Standalone HTML report with strict CSP and no external dependencies."""
from __future__ import annotations

from html import escape

STYLES = """
:root{color-scheme:dark;font-family:Inter,ui-sans-serif,system-ui,-apple-system,Segoe UI,sans-serif;background:#090713;color:#eeeafc}*{box-sizing:border-box}body{margin:0;background:radial-gradient(ellipse at 85% 0,#291447 0,transparent 42%),#090713;min-height:100vh}.wrap{max-width:1100px;margin:auto;padding:36px 24px 70px}header{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;border-bottom:1px solid #292039;padding-bottom:26px}.brand{font-weight:850;letter-spacing:.1em}.brand span{color:#bb9eff}.over{font-size:11px;letter-spacing:.2em;color:#a496bd;margin-bottom:7px}.pill{padding:8px 14px;border-radius:999px;background:#211735;color:#d2b9ff;font-size:12px;border:1px solid #45305e}h1{font-size:clamp(30px,5vw,52px);letter-spacing:-.04em;margin:30px 0 9px}p{color:#ad9fc2;line-height:1.7}.meta{color:#a496bd;font-size:13px;overflow-wrap:anywhere}.cards{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:29px 0}.card{background:linear-gradient(150deg,#211a34,#151121);border:1px solid #372b4d;border-radius:16px;padding:23px}.card b{display:block;font-size:37px;letter-spacing:-.05em}.card small{font-size:11px;letter-spacing:.13em;color:#a89dbd}.purple{color:#cbb7ff}.pink{color:#ffa1b5}.yellow{color:#fcd08c}h2{font-size:20px;margin:37px 0 18px}.finding{border:1px solid #342946;background:#171122;border-radius:15px;padding:22px;margin:12px 0;display:grid;grid-template-columns:1fr auto;gap:8px}.rule{font-weight:700;font-size:16px}.path{color:#9f91b7;font:12px ui-monospace,Consolas,monospace;overflow-wrap:anywhere;margin-top:8px}.rec{font-size:13px;color:#bbb0ce;margin-top:12px}.sev{font-size:11px;font-weight:800;letter-spacing:.13em;padding:7px 10px;border-radius:7px;height:max-content;background:#332038;color:#ffadc0}.sev.medium{background:#392d1e;color:#ffd38d}.sev.critical{background:#4a1528;color:#ff87aa}.sev.low{background:#23333b;color:#8ed8ef}.note{border-left:3px solid #a785f0;padding:10px 18px;margin:20px 0;background:#1a1427;border-radius:3px;color:#bbafd0;font-size:13px;line-height:1.7}.empty{padding:40px;text-align:center;border:1px dashed #4b3b61;border-radius:14px;color:#c1b1d6}.warnings{padding:15px;background:#382b22;border-radius:12px;color:#ffd59e;font-size:13px}.footer{border-top:1px solid #2b213e;padding-top:25px;margin-top:50px;color:#86789f;font-size:12px}@media(max-width:720px){.cards{grid-template-columns:repeat(2,1fr)}.wrap{padding:22px 16px}.card{padding:15px}.card b{font-size:30px}}
"""

def html_report(data: dict) -> str:
    counts = data["severity_counts"]
    cards = [("FILES SCANNED", data["files_scanned"], ""), ("FINDINGS", data["findings_count"], "purple"), ("HIGH", counts["high"], "pink"), ("CRITICAL", counts["critical"], "yellow")]
    cards_html = "".join(f'<div class="card"><b class="{tone}">{num}</b><small>{label}</small></div>' for label, num, tone in cards)
    findings = []
    for f in data["findings"]:
        sev = escape(f["severity"])
        findings.append(f'<div class="finding"><div><div class="rule">{escape(f["description"])}</div><div class="path">{escape(f["file"])}:{f["line"]} · {escape(f["rule_id"])} · fp:{escape(f["fingerprint"])}</div><div class="rec">{escape(f["recommendation"])}</div></div><div class="sev {sev}">{sev.upper()}</div></div>')
    rendered_findings = "".join(findings) if findings else '<div class="empty">No matching patterns found within the scanned scope.</div>'
    warning_text = '<div class="warnings">Coverage warnings: ' + escape("; ".join(data["warnings"])) + '</div>' if data["warnings"] else ''
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta http-equiv="Content-Security-Policy" content="default-src 'none'; style-src 'unsafe-inline'; img-src data:; base-uri 'none'; form-action 'none'"><title>SecretGuard · Security Scan</title><style>{STYLES}</style></head><body><main class="wrap"><header><div><div class="over">LOCAL-FIRST SECURITY</div><div class="brand">REQUIEM <span>/ SECRETGUARD</span></div></div><div class="pill">{escape(data["verdict"])}</div></header><h1>Security Overview<span class="purple">.</span></h1><p>Credential exposure checks for code you own. No credentials are sent anywhere.</p><div class="meta">TARGET: {escape(data["target"])}<br>GENERATED: {escape(data["scanned_at"])}</div><section class="cards">{cards_html}</section><div class="note">Findings are pattern matches, not proof that a key is valid. Values are never included in reports. A clean result is not a security certification. Ignored directories, binaries and archives are outside this MVP's scope.</div>{warning_text}<h2>Security findings ({data["findings_count"]})</h2>{rendered_findings}<div class="footer">REQUIEM SecretGuard v{escape(data["version"])} · Local scan · Authorized projects only</div></main></body></html>'''
